import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.CTx8wfac.js";const u=JSON.parse('{"title":"Layered architecture & DDD","description":"","frontmatter":{},"headers":[],"relativePath":"guide/layered-architecture.md","filePath":"guide/layered-architecture.md"}'),s={name:"guide/layered-architecture.md"};function r(i,e,l,c,d,p){return t(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="layered-architecture-ddd" tabindex="-1">Layered architecture &amp; DDD <a class="header-anchor" href="#layered-architecture-ddd" aria-label="Permalink to &quot;Layered architecture &amp; DDD&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title"><code>@banana-universe/ddd</code></p><p>The <strong><code>ddd</code></strong> package provides <strong>Entity</strong>, <strong>ValueObject</strong>, <strong>AggregateRoot</strong>, <strong>Repository</strong> / <strong>FindCriteria</strong>, <strong>UnitOfWork</strong>, and <strong>@DomainService</strong> / <strong>@ApplicationService</strong> (layer metadata + <code>Injectable</code>). Use <strong><code>bananajs generate module &lt;name&gt;</code></strong> for a full layered scaffold, or <strong><code>bananajs ai generate --module</code></strong> for LLM-assisted generation.</p></div><h2 id="manual-layout" tabindex="-1">Manual layout <a class="header-anchor" href="#manual-layout" aria-label="Permalink to &quot;Manual layout&quot;">​</a></h2><p>You can structure code as <strong>domain / application / infrastructure</strong> without the package—BananaJS does not force a flat layout. <strong>Plugins</strong> (<code>TypeOrmPlugin</code>, <code>MongoosePlugin</code>, …) attach <strong>infrastructure</strong> at the edges while <strong>controllers</strong> stay thin.</p><h2 id="generated-module-shape" tabindex="-1">Generated module shape <a class="header-anchor" href="#generated-module-shape" aria-label="Permalink to &quot;Generated module shape&quot;">​</a></h2><p><code>bananajs generate module &lt;name&gt; [--orm typeorm|mongoose|none] [--out ./src]</code> produces a <strong>bounded context</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/&lt;name&gt;/</span></span>
<span class="line"><span>  domain/</span></span>
<span class="line"><span>    &lt;Name&gt;.entity.ts</span></span>
<span class="line"><span>    &lt;Name&gt;.repository.ts      # interface — persistence contract</span></span>
<span class="line"><span>    &lt;Name&gt;.service.ts         # @DomainService</span></span>
<span class="line"><span>  application/</span></span>
<span class="line"><span>    &lt;Name&gt;.app-service.ts     # @ApplicationService</span></span>
<span class="line"><span>    &lt;Name&gt;.dto.ts</span></span>
<span class="line"><span>  infrastructure/</span></span>
<span class="line"><span>    typeorm/&lt;Name&gt;.typeorm-repository.ts   # or mongoose/ / in-memory</span></span>
<span class="line"><span>  &lt;Name&gt;.controller.ts</span></span></code></pre></div><h2 id="principles" tabindex="-1">Principles <a class="header-anchor" href="#principles" aria-label="Permalink to &quot;Principles&quot;">​</a></h2><ul><li><strong>Domain</strong> — business rules and model; <strong>no Express</strong>, <strong>no ORM entities</strong> in this layer</li><li><strong>Application</strong> — orchestration, use cases, DTOs at the boundary</li><li><strong>Infrastructure</strong> — TypeORM / Mongoose / messaging / external APIs; <strong>mappers</strong> <code>toDomain</code> / <code>toPersistence</code> keep persistence honest</li></ul><h2 id="repository-model" tabindex="-1">Repository model <a class="header-anchor" href="#repository-model" aria-label="Permalink to &quot;Repository model&quot;">​</a></h2><p><strong><code>FindCriteria&lt;T&gt;</code></strong> (eq / in / like / gt / lt, sorting, paging) keeps queries <strong>explicit and testable</strong>—not a vague <code>Partial&lt;T&gt;</code>.</p><h2 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h2><p><strong><code>bananajs generate module &lt;name&gt; --orm typeorm|mongoose|none</code></strong> scaffolds the infrastructure stub; <strong><code>typeorm</code></strong> is the default when stdin is not a TTY.</p><h2 id="transactions" tabindex="-1">Transactions <a class="header-anchor" href="#transactions" aria-label="Permalink to &quot;Transactions&quot;">​</a></h2><p><strong><code>UnitOfWork</code></strong> plus ORM-specific implementations align application services that touch multiple aggregates; <strong><code>@Transactional</code></strong> in plugins exists at the persistence layer for TypeORM and Mongoose.</p><h2 id="learn-more" tabindex="-1">Learn more <a class="header-anchor" href="#learn-more" aria-label="Permalink to &quot;Learn more&quot;">​</a></h2><ul><li><a href="/banana-universe/guide/philosophy.html">Philosophy</a> — DDD and product direction</li><li><a href="/banana-universe/tooling/ai-module-generation.html">AI module generation</a> — LLM-driven <code>ai generate --module</code></li><li><a href="/banana-universe/integrations/typeorm.html">TypeORM integration</a> — plugins and repository adapters</li></ul>`,17)])])}const h=a(s,[["render",r]]);export{u as __pageData,h as default};
